/* ==========================================================================
   Isolated Component Stylesheet (Zero Global Selectors)
   ========================================================================== */

/* Component Context Container */
.snd-regulator-context {
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 60px 0px;
}

/* Soundboard Panel Box */
.snd-regulator-context .snd-fader-panel {
  background: linear-gradient(145deg, #232329, #1e1e24);
  padding: 40px 30px;
  border-radius: 12px;
  box-shadow:
    inset 1px 1px 1px rgba(255, 255, 255, 0.05),
    10px 10px 30px rgba(0, 0, 0, 0.5);
  border: 1px solid #151518;
  display: flex;
  flex-direction: column;
  align-items: center;
  width: 100px;
  box-sizing: border-box;
}

/* Channel Header Text */
.snd-regulator-context .snd-fader-label {
  color: #8e8e93;
  font-family:
    system-ui,
    -apple-system,
    sans-serif;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 1.5px;
  margin-bottom: 25px;
  text-transform: uppercase;
}

/* Track Area & Spatial Tick Mark Layout */
.snd-regulator-context .snd-fader-container {
  position: relative;
  height: 300px;
  width: 60px;
  display: flex;
  justify-content: center;
  background-image: linear-gradient(to bottom, #444 2px, transparent 2px),
    linear-gradient(to bottom, #444 2px, transparent 2px);
  background-size: 15px 30px;
  background-position:
    left center,
    right center;
  background-repeat: repeat-y;
  box-sizing: border-box;
}

/* Input Range Track Reset & Rotation Styling */
.snd-regulator-context .snd-audio-fader {
  -webkit-appearance: none;
  appearance: none;
  width: 280px;
  height: 8px;
  background: #0d0d10;
  border-radius: 4px;
  outline: none;
  position: absolute;
  top: 136px;
  transform: rotate(-90deg);
  cursor: pointer;
  box-shadow:
    inset 1px 1px 3px rgba(0, 0, 0, 0.8),
    1px 1px 1px rgba(255, 255, 255, 0.05);
  margin: 0;
}

/* Custom Knob Styling (WebKit Browsers) */
.snd-regulator-context .snd-audio-fader::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 36px;
  height: 24px;
  border-radius: 3px;
  background: linear-gradient(
    to right,
    #3a3a42 0%,
    #555560 40%,
    #1a1a1f 45%,
    #d12b2b 48%,
    #d12b2b 52%,
    #1a1a1f 55%,
    #555560 60%,
    #3a3a42 100%
  );
  box-shadow:
    0px 2px 8px rgba(0, 0, 0, 0.7),
    0px 5px 15px rgba(0, 0, 0, 0.5),
    inset 0 1px 1px rgba(255, 255, 255, 0.2);
  border: 1px solid #111;
  transition: transform 0.1s ease;
}

.snd-regulator-context .snd-audio-fader::-webkit-slider-thumb:active {
  transform: scale(1.05);
}

/* Custom Knob Styling (Firefox Variants) */
.snd-regulator-context .snd-audio-fader::-moz-range-thumb {
  width: 36px;
  height: 24px;
  border-radius: 3px;
  background: linear-gradient(
    to right,
    #3a3a42 0%,
    #555560 40%,
    #1a1a1f 45%,
    #d12b2b 48%,
    #d12b2b 52%,
    #1a1a1f 55%,
    #555560 60%,
    #3a3a42 100%
  );
  box-shadow:
    0px 2px 8px rgba(0, 0, 0, 0.7),
    0px 5px 15px rgba(0, 0, 0, 0.5);
  border: 1px solid #111;
}
